import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.lifecycle.ViewModel
import androidx.lifecycle.compose.collectAsStateWithLifecycle
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow

sealed interface DeviceUiState {
    data object Loading : DeviceUiState
    data class Online(val name: String, val cpu: Int) : DeviceUiState
    data object Offline : DeviceUiState
    data class Error(val message: String) : DeviceUiState
}

class DeviceViewModel : ViewModel() {
    private val _state = MutableStateFlow<DeviceUiState>(DeviceUiState.Loading)
    val state: StateFlow<DeviceUiState> = _state
    fun setOnline(name: String, cpu: Int) { _state.value = DeviceUiState.Online(name, cpu) }
    fun setOffline() { _state.value = DeviceUiState.Offline }
}

@Composable
fun DeviceStatusScreen(vm: DeviceViewModel) {
    val state by vm.state.collectAsStateWithLifecycle()
    when (val s = state) {
        DeviceUiState.Loading -> CircularProgressIndicator()
        is DeviceUiState.Online -> Text("${s.name}: online, CPU ${s.cpu}%")
        DeviceUiState.Offline -> Text("Offline")
        is DeviceUiState.Error -> Text("Error: ${s.message}")
    }
}
