#include <WiFi.h>

const char* SSID = "YOUR_SSID";
const char* PASS = "YOUR_PASSWORD";
unsigned long lastAttempt = 0;
unsigned long retryMs = 1000;
const unsigned long MAX_RETRY_MS = 30000;

void beginConnect() {
  WiFi.mode(WIFI_STA);
  WiFi.begin(SSID, PASS);
  lastAttempt = millis();
}

void setup() {
  Serial.begin(115200);
  beginConnect();
}

void loop() {
  if (WiFi.status() == WL_CONNECTED) {
    retryMs = 1000;
    // other non-blocking work here
    return;
  }

  const unsigned long now = millis();
  if (now - lastAttempt >= retryMs) {
    WiFi.disconnect();
    WiFi.begin(SSID, PASS);
    lastAttempt = now;
    retryMs = min(retryMs * 2, MAX_RETRY_MS);
  }

  // other non-blocking work here
}
