import sqlite3
import uuid
from fastapi import FastAPI, Header, HTTPException
from pydantic import BaseModel

app = FastAPI()
DB = 'tasks.db'

class TaskIn(BaseModel):
    intent: str
    payload: dict = {}

def db():
    con = sqlite3.connect(DB)
    con.row_factory = sqlite3.Row
    con.execute('CREATE TABLE IF NOT EXISTS tasks (id TEXT PRIMARY KEY, idem TEXT UNIQUE NOT NULL, intent TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL)')
    return con

@app.post('/tasks')
def create_task(body: TaskIn, idempotency_key: str = Header(..., alias='Idempotency-Key')):
    import json
    con = db()
    try:
        row = con.execute('SELECT * FROM tasks WHERE idem=?', (idempotency_key,)).fetchone()
        if row:
            return dict(row)
        task_id = str(uuid.uuid4())
        con.execute('INSERT INTO tasks VALUES (?,?,?,?,?)', (task_id, idempotency_key, body.intent, json.dumps(body.payload), 'queued'))
        con.commit()
        return dict(con.execute('SELECT * FROM tasks WHERE id=?', (task_id,)).fetchone())
    except sqlite3.IntegrityError:
        row = con.execute('SELECT * FROM tasks WHERE idem=?', (idempotency_key,)).fetchone()
        if not row:
            raise HTTPException(409, 'Idempotency conflict')
        return dict(row)
    finally:
        con.close()
