#include <stddef.h>

template <size_t N>
class MovingAverage {
 public:
  void add(float value) {
    if (count_ < N) {
      data_[index_] = value;
      sum_ += value;
      ++count_;
    } else {
      sum_ -= data_[index_];
      data_[index_] = value;
      sum_ += value;
    }
    index_ = (index_ + 1) % N;
  }

  float value() const {
    return count_ == 0 ? 0.0f : sum_ / static_cast<float>(count_);
  }

 private:
  float data_[N]{};
  float sum_ = 0.0f;
  size_t index_ = 0;
  size_t count_ = 0;
};
